// The third-party licence list of About (generated by `scripts/licenses.mjs`, bundled, no network). Loaded on demand
// because it is large; filterable by name.
import { Button, Input, t } from "@tessera/ui";
import { useMemo, useState } from "react";

interface Entry {
  name: string;
  version: string;
  license: string;
  source: "rust" | "npm";
}

export function Licenses() {
  const [entries, setEntries] = useState<Entry[] | null>(null);
  const [query, setQuery] = useState("");
  const [failed, setFailed] = useState(false);
  const shown = useMemo(() => {
    const q = query.trim().toLowerCase();
    return (entries ?? []).filter(
      (e) => q === "" || e.name.toLowerCase().includes(q) || e.license.toLowerCase().includes(q),
    );
  }, [entries, query]);

  if (!entries) {
    return (
      <div className="flex flex-col gap-1">
        <Button
          size="sm"
          variant="secondary"
          data-licenses-show
          onClick={() =>
            void import("./licenses.json")
              .then((module) => setEntries(module.default as Entry[]))
              .catch(() => setFailed(true))
          }
        >
          {t("about.licenses")}
        </Button>
        {failed && <p className="m-0 text-xs text-danger">{t("about.licensesFailed")}</p>}
      </div>
    );
  }
  return (
    <div className="flex flex-col gap-2" data-licenses>
      <Input
        aria-label={t("about.licensesFilter")}
        placeholder={t("about.licensesFilter")}
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <p className="m-0 text-xs text-muted">{t("about.licensesCount", { count: shown.length })}</p>
      <ul className="m-0 max-h-56 list-none overflow-auto p-0 font-mono text-xs">
        {shown.slice(0, 400).map((e) => (
          <li key={`${e.source}:${e.name}@${e.version}`} className="flex gap-2">
            <span className="min-w-0 flex-1 truncate">{e.name}</span>
            <span className="text-muted">{e.version}</span>
            <span className="w-32 shrink-0 truncate text-muted">{e.license}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}
